import{_ as h,o as i,c as t,a2 as a}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Việc học thật ra diễn ra thế nào","description":"","frontmatter":{},"headers":[],"relativePath":"learning/index.md","filePath":"learning/index.md"}'),c={name:"learning/index.md"};function e(r,n,o,g,u,l){return i(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="viec-hoc-that-ra-dien-ra-the-nao" tabindex="-1">Việc học thật ra diễn ra thế nào <a class="header-anchor" href="#viec-hoc-that-ra-dien-ra-the-nao" aria-label="Permalink to &quot;Việc học thật ra diễn ra thế nào&quot;">​</a></h1><p>Trên trang này# Việc học thật ra diễn ra thế nào <a href="#viec-hoc-that-ra-dien-ra-the-nao">​</a> Hầu hết những gì trông giống &quot;đang học&quot; thật ra chỉ là <em>đang tiếp xúc với nội dung</em>. Nhóm này giải thích sự khác nhau đó, và bốn kỹ thuật có bằng chứng vững nhất để biến tiếp xúc thành hiểu. Có một quan sát khó chịu mà bất kỳ ai từng ôn thi đều gặp: đọc lại bài giảng lần thứ ba cho <strong>cảm giác</strong> hiểu rất rõ, nhưng gấp sách vào thì không viết lại được. Cảm giác trôi chảy khi đọc không phải bằng chứng của việc học. Nó chỉ là bằng chứng rằng nội dung đang quen mắt. Điều này quan trọng với gia đình, vì phần lớn quyết định học tập ở nhà đều dựa trên cảm giác: con ngồi bàn hai tiếng, vở ghi kín, làm hết đề — vậy là đang học tốt. Ba tín hiệu đó đo thời gian và khối lượng, không đo việc học.</p><h2 id="hai-loai-trai-nghiem-hai-muc-đich-​" tabindex="-1">Hai loại trải nghiệm, hai mục đích <a href="#hai-loai-trai-nghiem-hai-muc-đich">​</a> <a class="header-anchor" href="#hai-loai-trai-nghiem-hai-muc-đich-​" aria-label="Permalink to &quot;Hai loại trải nghiệm, hai mục đích [​](#hai-loai-trai-nghiem-hai-muc-đich)&quot;">​</a></h2><p>Nemo12 tách rạch ròi mọi hoạt động thành hai loại: <a href="/learning/learning-experience"><strong>Learning Experience</strong>Thiết kế để làm learner giỏi lên. Được phép có gợi ý, bài mẫu, giải thích, thử sai. Đo bằng &quot;học được gì&quot;.</a><a href="/learning/assessment-experience"><strong>Assessment Experience</strong>Thiết kế để biết learner đang ở đâu. Không dạy trong lúc đo. Đo bằng &quot;biết thêm được gì về learner&quot;.</a>Trộn hai thứ này lại là lỗi phổ biến nhất trong giáo dục — và cũng là lỗi tốn kém nhất. <a href="/learning/assessment-khac-learning">Vì sao Assessment không đồng nghĩa với Learning →</a></p><h2 id="bon-ky-thuat-va-vi-sao-chinh-bon-cai-nay-​" tabindex="-1">Bốn kỹ thuật, và vì sao chính bốn cái này <a href="#bon-ky-thuat-va-vi-sao-chinh-bon-cai-nay">​</a> <a class="header-anchor" href="#bon-ky-thuat-va-vi-sao-chinh-bon-cai-nay-​" aria-label="Permalink to &quot;Bốn kỹ thuật, và vì sao chính bốn cái này [​](#bon-ky-thuat-va-vi-sao-chinh-bon-cai-nay)&quot;">​</a></h2><p>Trong hàng trăm kỹ thuật dạy học, có một nhóm nhỏ được kiểm chứng lặp lại qua nhiều thập kỷ, nhiều môn, nhiều độ tuổi. Nemo12 xây phần lớn trải nghiệm học quanh bốn kỹ thuật đó: Kỹ thuậtGiải bài toán gìCảm giác của learner<a href="/learning/scaffolding">Scaffolding</a>Bài quá khó thì learner bỏ cuộc, quá dễ thì không học được gìKhó vừa đủ để phải nghĩ<a href="/learning/retrieval-practice">Retrieval Practice</a>Đọc lại tạo cảm giác hiểu giảKhó hơn đọc lại — và đó là lý do nó hiệu quả<a href="/learning/worked-examples">Worked Examples</a>Người mới bị quá tải nếu phải tự mò từ đầuNhẹ đầu, thấy rõ từng bước<a href="/learning/spaced-practice">Spaced Practice</a>Học dồn thì nhớ nhanh, quên cũng nhanhHơi khó chịu vì phải nhớ lại thứ đã mờBa trong bốn kỹ thuật này khiến việc học <strong>cảm thấy khó hơn</strong> so với cách học truyền thống. Đó không phải tác dụng phụ — đó chính là cơ chế. Trong nghiên cứu học tập, hiện tượng này có tên: <em>khó khăn có ích</em> (desirable difficulty). Điều đó cũng giải thích một hiểu lầm hay gặp: phụ huynh thấy con làm bài trên Nemo12 chậm hơn, sai nhiều hơn so với khi làm phiếu bài tập quen thuộc, và kết luận là &quot;hệ thống ra đề khó quá&quot;. Thực tế thường ngược lại — phiếu bài tập quen thuộc đang cho làm lại thứ con đã biết.</p><h2 id="hoc-ky-đen-đau-thi-đu-​" tabindex="-1">&quot;Học kỹ&quot; đến đâu thì đủ <a href="#hoc-ky-đen-đau-thi-đu">​</a> <a class="header-anchor" href="#hoc-ky-đen-đau-thi-đu-​" aria-label="Permalink to &quot;&quot;Học kỹ&quot; đến đâu thì đủ [​](#hoc-ky-đen-đau-thi-đu)&quot;">​</a></h2><p>Câu hỏi này ít được hỏi, nhưng nó quyết định phần lớn hiệu quả thời gian. Học kỹ hơn luôn <em>có thêm</em> giá trị — nhưng giá trị thêm giảm dần, trong khi thời gian thì hữu hạn và luôn có một mảng kiến thức khác đang yếu hơn. Nemo12 định nghĩa &quot;học kỹ&quot; bằng ba con số cho từng mục tiêu học tập — mức sâu cần đạt, mức vững mong muốn, và độ chắc chắn tối thiểu của kết luận — chứ không bằng cảm giác. Khi cả ba đạt ngưỡng, hệ thống <strong>chủ động chuyển learner sang chỗ khác</strong>, kể cả khi con vẫn còn muốn làm thêm. <a href="/learning/hoc-ky">Đọc về giới hạn của &quot;học kỹ&quot; →</a></p><h2 id="neu-ban-chi-nho-mot-cau-tu-nhom-nay-​" tabindex="-1">Nếu bạn chỉ nhớ một câu từ nhóm này <a href="#neu-ban-chi-nho-mot-cau-tu-nhom-nay">​</a> <a class="header-anchor" href="#neu-ban-chi-nho-mot-cau-tu-nhom-nay-​" aria-label="Permalink to &quot;Nếu bạn chỉ nhớ một câu từ nhóm này [​](#neu-ban-chi-nho-mot-cau-tu-nhom-nay)&quot;">​</a></h2><p>Việc học xảy ra khi learner phải tự lấy kiến thức ra khỏi đầu mình, chứ không phải khi kiến thức đi vào.</p>',10)])])}const k=h(c,[["render",e]]);export{s as __pageData,k as default};
